
<style>
  :root{
    --milk:#F8F0ED; --ink:#3A2A2A; --rose:#F0B4C4;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html,body{height:100%;overflow:hidden}
  body{
    background:transparent;
    opacity:0;transition:opacity 1.1s ease;
  }
  body.ready{opacity:1}
  .glow{
    position:fixed;inset:0;
    background:radial-gradient(58% 62% at 50% 54%, rgba(255,248,245,.92) 0%, rgba(255,248,245,0) 70%);
    pointer-events:none;
  }
  .stage{position:fixed;inset:0}
  canvas{display:block;width:100%;height:100%}
  /* курсор */
  .cur,.ring{position:fixed;top:0;left:0;pointer-events:none;z-index:9;will-change:transform}
  .cur{width:7px;height:7px;margin:-3.5px 0 0 -3.5px;border-radius:50%;background:var(--rose)}
  .ring{width:34px;height:34px;margin:-17px 0 0 -17px;border-radius:50%;
        border:1px solid rgba(58,42,42,.28);transition:width .25s,height .25s,margin .25s,border-color .25s}
  @media (hover:hover) and (pointer:fine){ body{cursor:none} }
  @media (hover:none){ .cur,.ring{display:none} }
  @media (prefers-reduced-motion:reduce){ body{transition:none} }
</style>

  
  <div class="stage"><canvas id="cow" aria-label="Коровка Black Milk: её глаза следят за курсором." role="img"></canvas></div>
  <div class="cur" id="cur"></div>
  <div class="ring" id="ring"></div>
<script>
(() => {
  "use strict";
  const IW = 800, IH = 820;
  const EYES = [
    {x:325, y:237, mx:9,  my:6},
    {x:521, y:236, mx:11, my:7}
  ];
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  const base = new Image(); base.decoding='async';
  base.src = 'data:image/webp;base64,';
  const pupils = [new Image(), new Image()];
  pupils[0].src = 'data:image/webp;base64,';
  pupils[1].src = 'data:image/webp;base64,';

  const cv = document.getElementById('cow');
  const ctx = cv.getContext('2d');
  let W=0,H=0,dpr=1;
  let geo = {s:1,dw:1,dh:1,ox:0,oy:0};

  function layout(){
    const pad = W < 760 ? 1.10 : 1.5;         // на телефоне коровка крупнее
    const s = Math.min(W/(IW*pad), H/(IH*1.22));
    const dw = IW*s, dh = IH*s;
    geo = { s, dw, dh, ox:(W-dw)/2, oy:(H-dh)/2 + dh*0.02 };
  }

  function draw(gx, gy){
    const {s,dw,dh,ox,oy} = geo;
    ctx.clearRect(0,0,W,H);

    ctx.save();
    ctx.translate(ox+dw/2, oy+dh-2); ctx.scale(1,0.10);
    const sh = ctx.createRadialGradient(0,0,0,0,0,dw*0.42);
    sh.addColorStop(0,'rgba(70,44,44,.26)'); sh.addColorStop(.55,'rgba(70,44,44,.09)'); sh.addColorStop(1,'rgba(70,44,44,0)');
    ctx.fillStyle = sh; ctx.beginPath(); ctx.arc(0,0,dw*0.42,0,Math.PI*2); ctx.fill();
    ctx.restore();

    ctx.drawImage(base, ox, oy, dw, dh);        // тело неподвижно

    EYES.forEach((e,i) => {                      // двигаются только зрачки
      const sp = pupils[i];
      if(!sp.complete || !sp.naturalWidth) return;
      const r = sp.naturalWidth/2;
      const cx = ox + e.x*s + gx*e.mx*s;
      const cy = oy + e.y*s + gy*e.my*s;
      ctx.drawImage(sp, cx-r*s, cy-r*s, sp.naturalWidth*s, sp.naturalHeight*s);
    });
  }

  function resize(){
    dpr = Math.min(window.devicePixelRatio||1, 2);
    W = Math.max(1, window.innerWidth); H = Math.max(1, window.innerHeight);
    cv.width = Math.round(W*dpr); cv.height = Math.round(H*dpr);
    ctx.setTransform(dpr,0,0,dpr,0,0);
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = 'high';
    layout();
    if(base.complete) draw(curX, curY);
  }

  let targetX=0, targetY=0, curX=0, curY=0, attentionUntil=0, lastDraw=0;

  function loop(now){
    requestAnimationFrame(loop);
    if(!base.complete) return;
    const ease = reduced ? 1 : 0.12;
    const att = now < attentionUntil;
    curX += ((att?0:targetX)-curX)*ease;
    curY += ((att?0:targetY)-curY)*ease;
    if(now-lastDraw < 28) return;
    lastDraw = now;
    draw(curX, curY);
  }

  function point(x,y){
    const hx = geo.ox + geo.dw/2, hy = geo.oy + geo.dh*0.28;
    targetX = Math.max(-1, Math.min(1, (x-hx)/(W*0.42)));
    targetY = Math.max(-1, Math.min(1, (y-hy)/(H*0.42)));
  }
  window.addEventListener('pointermove', e => { point(e.clientX,e.clientY); moveCursor(e.clientX,e.clientY); }, {passive:true});
  window.addEventListener('touchmove',  e => { const p=e.touches[0]; if(p) point(p.clientX,p.clientY); }, {passive:true});
  window.addEventListener('touchstart', e => { const p=e.touches[0]; if(p) point(p.clientX,p.clientY); }, {passive:true});
  window.addEventListener('click', () => { attentionUntil = performance.now()+1600; });

  const cur=document.getElementById('cur'), ring=document.getElementById('ring');
  let rx=0,ry=0,cx=0,cy=0;
  function moveCursor(x,y){ cx=x; cy=y; cur.style.transform=`translate3d(${x}px,${y}px,0)`; }
  (function ringLoop(){
    rx+=(cx-rx)*0.18; ry+=(cy-ry)*0.18;
    ring.style.transform=`translate3d(${rx}px,${ry}px,0)`;
    requestAnimationFrame(ringLoop);
  })();

  let done=0;
  function ready(){
    if(++done < 3) return;
    resize();
    document.body.classList.add('ready');
  }
  [base,pupils[0],pupils[1]].forEach(im => { if(im.complete) ready(); else { im.onload=ready; im.onerror=ready; } });

  window.addEventListener('resize', resize);
  window.addEventListener('orientationchange', () => setTimeout(resize,120));
  requestAnimationFrame(loop);
})();
</script>

<script>
/* relais: le curseur de la page parente pilote le regard (ajouté pour l'intégration) */
window.addEventListener('message', (e) => {
  const d = e.data;
  if (!d || d.bmCow !== 1) return;
  const ev = new PointerEvent('pointermove', {
    clientX: d.x * window.innerWidth,
    clientY: d.y * window.innerHeight,
    bubbles: true
  });
  window.dispatchEvent(ev);
}, false);
</script>
